"""Comprehensive tests for synthstr.stringy module."""

from __future__ import annotations

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ---------------------------------------------------------------------------
# reverse
# ---------------------------------------------------------------------------

class TestReverse:
    def test_simple(self):
        assert reverse("hello") == "olleh"

    def test_empty(self):
        assert reverse("") == ""

    def test_single_char(self):
        assert reverse("x") == "x"

    def test_palindrome_word(self):
        assert reverse("racecar") == "racecar"

    def test_whitespace(self):
        assert reverse("a b") == "b a"

    def test_unicode(self):
        assert reverse("café") == "éfac"

    def test_emoji(self):
        assert reverse("ab🙂") == "🙂ba"

    def test_digits(self):
        assert reverse("12345") == "54321"

    def test_special_characters(self):
        assert reverse("!@#") == "#@!"

    def test_multiline(self):
        assert reverse("a\nb") == "b\na"


# ---------------------------------------------------------------------------
# is_palindrome
# ---------------------------------------------------------------------------

class TestIsPalindrome:
    def test_simple_true(self):
        assert is_palindrome("racecar") is True

    def test_simple_false(self):
        assert is_palindrome("hello") is False

    def test_empty(self):
        assert is_palindrome("") is True

    def test_single_char(self):
        assert is_palindrome("a") is True

    def test_ignores_case(self):
        assert is_palindrome("RaceCar") is True

    def test_ignores_non_alnum(self):
        assert is_palindrome("A man, a plan, a canal: Panama") is True

    def test_spaces_only(self):
        # No alnum chars → cleaned is empty → palindrome
        assert is_palindrome("   ") is True

    def test_punctuation_only(self):
        assert is_palindrome("!@#$%") is True

    def test_even_length_palindrome(self):
        assert is_palindrome("abba") is True

    def test_even_length_non_palindrome(self):
        assert is_palindrome("abcd") is False

    def test_numeric_palindrome(self):
        assert is_palindrome("12321") is True

    def test_mixed_alnum(self):
        assert is_palindrome("Was it a car or a cat I saw?") is True

    def test_unicode_non_alnum_ignored(self):
        # dashes and colons stripped; letters compared
        assert is_palindrome("a-b-a") is True

    def test_unicode_letters(self):
        # "à" is alphanumeric; "àbà" reversed is "àbà" → palindrome
        assert is_palindrome("àbà") is True


# ---------------------------------------------------------------------------
# word_count
# ---------------------------------------------------------------------------

class TestWordCount:
    def test_simple(self):
        assert word_count("hello world") == 2

    def test_empty(self):
        assert word_count("") == 0

    def test_single_word(self):
        assert word_count("hello") == 1

    def test_multiple_spaces(self):
        assert word_count("a  b   c") == 3

    def test_leading_trailing_spaces(self):
        assert word_count("  hello  ") == 1

    def test_tabs_and_newlines(self):
        assert word_count("a\tb\nc") == 3

    def test_only_whitespace(self):
        assert word_count("   \t\n  ") == 0

    def test_long_sentence(self):
        sentence = "the quick brown fox jumps over the lazy dog"
        assert word_count(sentence) == 9


# ---------------------------------------------------------------------------
# truncate
# ---------------------------------------------------------------------------

class TestTruncate:
    def test_no_truncation_needed(self):
        assert truncate("hi", 5) == "hi"

    def test_exact_length(self):
        assert truncate("hello", 5) == "hello"

    def test_truncation_with_ellipsis(self):
        result = truncate("hello world", 5)
        assert result == "hell\u2026"
        assert len(result) == 5

    def test_limit_zero(self):
        assert truncate("hello", 0) == ""

    def test_limit_one(self):
        result = truncate("hello", 1)
        assert result == "\u2026"
        assert len(result) == 1

    def test_negative_limit_raises(self):
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_empty_string_any_limit(self):
        assert truncate("", 0) == ""
        assert truncate("", 5) == ""

    def test_unicode_truncation(self):
        result = truncate("café latte", 5)
        assert result == "caf\u00e9\u2026"
        assert len(result) == 5

    def test_result_never_exceeds_limit(self):
        for limit in range(0, 20):
            result = truncate("a long test string here", limit)
            assert len(result) <= limit

    def test_no_ellipsis_when_fits(self):
        assert truncate("abc", 10) == "abc"
        assert "\u2026" not in truncate("abc", 10)

    def test_large_limit(self):
        s = "short"
        assert truncate(s, 10000) == s

